import { FormRef } from '@/checkout/types/storefront-account';
import { RefObject } from 'preact';

export function validateForm(
  formName: string,
  formRef: RefObject<FormRef>
): boolean {
  const formElement = document.forms.namedItem(formName);

  if (!formElement) {
    return true;
  }

  const isVisible = formElement && formElement.offsetParent !== null;
  if (!isVisible) {
    return true;
  }

  formElement.setAttribute('novalidate', '');

  if (formRef && formRef.current) {
    return formRef.current.handleValidationSubmit(false);
  }

  return formElement.checkValidity();
}
